document.addEventListener("DOMContentLoaded",()=>{const s=t=>{const e=t.closest("tr");if(!e)return;const r=e.querySelector("[data-mobile-meta]");r&&(t.checked?(r.classList.remove("grid-rows-[0fr]"),r.classList.add("grid-rows-[1fr]")):(r.classList.remove("grid-rows-[1fr]"),r.classList.add("grid-rows-[0fr]")))};document.querySelectorAll('input[name="work_ids"], input[name="employee_ids"]').forEach(t=>s(t)),document.addEventListener("change",t=>{const e=t.target;e instanceof HTMLInputElement&&(e.name==="work_ids"||e.name==="employee_ids")&&s(e)})});
